def format_puzzle_move_label_from_fen(fen, move_uci, fallback=""):
    move_text = str(move_uci or "").strip()
    if not move_text:
        return str(fallback or "").strip()
    board_fen = str(fen or "").strip()
    if chesslib is not None and board_fen:
        try:
            board = chesslib.Board(board_fen)
            move_obj = chesslib.Move.from_uci(move_text)
            if move_obj in board.legal_moves:
                return board.san(move_obj)
        except Exception:
            pass
    return str(fallback or move_text).strip()


def default_chess_courses():
    return {
        "courses": [],
        "updated_at": "",
    }


def load_chess_courses():
    raw = load_json_file(CHESS_COURSES_PATH, default_chess_courses())
    if not isinstance(raw, dict):
        raw = {}
    data = default_chess_courses()
    courses = raw.get("courses", [])
    data["courses"] = [dict(item) for item in courses if isinstance(item, dict)] if isinstance(courses, list) else []
    data["updated_at"] = str(raw.get("updated_at", "") or "").strip()
    if CHESS_COURSES_PATH.exists() and data != raw:
        save_json_file(CHESS_COURSES_PATH, data)
    return data


