def normalize_reading_status(value):
    normalized = str(value or "").strip().lower()
    return normalized if normalized in READING_STATUSES else "unread"


def normalize_reading_bool(value, default=True):
    if isinstance(value, bool):
        return value
    if value is None:
        return bool(default)
    normalized = str(value).strip().lower()
    if normalized in {"1", "true", "yes", "on", "active", "enabled"}:
        return True
    if normalized in {"0", "false", "no", "off", "paused", "disabled", "inactive"}:
        return False
    return bool(default)


def normalize_reading_url(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    parsed = urllib.parse.urlsplit(raw)
    if not parsed.scheme or not parsed.netloc:
        return raw.rstrip("/")
    path = parsed.path.rstrip("/") or parsed.path or "/"
    return urllib.parse.urlunsplit((parsed.scheme.lower(), parsed.netloc.lower(), path, parsed.query, ""))


def normalize_reading_dedupe_url(value):
    normalized = normalize_reading_url(value)
    if not normalized:
        return ""
    parsed = urllib.parse.urlsplit(normalized)
    query_pairs = [
        (key, val)
        for key, val in urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
        if not key.lower().startswith(("utm_", "fbclid", "gclid"))
    ]
    return urllib.parse.urlunsplit((
        parsed.scheme,
        parsed.netloc[4:] if parsed.netloc.startswith("www.") else parsed.netloc,
        parsed.path.rstrip("/") or parsed.path or "/",
        urllib.parse.urlencode(query_pairs, doseq=True),
        "",
    ))


def normalize_reading_dedupe_title(value):
    text = normalize_reading_space(value)
    if not text:
        return ""
    text = text.casefold()
    text = re.sub(r"[\"'`’“”‘]+", "", text)
    text = re.sub(r"[\W_]+", " ", text, flags=re.UNICODE)
    return normalize_reading_space(text)


def reading_entry_dedupe_scope(entry):
    entry = entry if isinstance(entry, dict) else {}
    source_id = str(entry.get("source_id", "") or "").strip()
    if source_id:
        return source_id.lower()
    source_name = normalize_reading_space(entry.get("source", ""))
    if source_name:
        return source_name.casefold()
    for field in ("url", "original_url", "canonical_url"):
        normalized_url = normalize_reading_dedupe_url(entry.get(field, ""))
        if not normalized_url:
            continue
        host = urllib.parse.urlsplit(normalized_url).netloc.lower()
        if host:
            return host
    return ""


def reading_entry_dedupe_published_day(entry):
    entry = entry if isinstance(entry, dict) else {}
    timestamp = parse_timestamp(entry.get("published_at", "")) or parse_timestamp(entry.get("added_at", "")) or parse_timestamp(entry.get("imported_at", ""))
    if not timestamp:
        return ""
    try:
        return timestamp.date().isoformat()
    except Exception:
        return ""


def reading_entry_dedupe_keys(entry):
    entry = entry if isinstance(entry, dict) else {}
    keys = set()
    source_id = str(entry.get("source_id", "") or "").strip()
    for field in ("url", "original_url", "canonical_url"):
        key_url = normalize_reading_dedupe_url(entry.get(field, ""))
        if key_url:
            keys.add(f"url:{key_url}")
    for field in ("external_id", "guid", "entry_guid", "feed_entry_id"):
        value = str(entry.get(field, "") or "").strip()
        if value:
            keys.add(f"id:{source_id}:{value.lower()}" if source_id else f"id:{value.lower()}")
    title_key = normalize_reading_dedupe_title(entry.get("title", ""))
    dedupe_scope = reading_entry_dedupe_scope(entry)
    published_day = reading_entry_dedupe_published_day(entry)
    if title_key and dedupe_scope and published_day:
        keys.add(f"title_day:{dedupe_scope}:{published_day}:{title_key}")
    if title_key and dedupe_scope and not keys:
        keys.add(f"title:{dedupe_scope}:{title_key}")
    return keys


def reading_entry_sort_key(entry):
    entry = entry if isinstance(entry, dict) else {}
    published = parse_timestamp(entry.get("published_at", ""))
    added = parse_timestamp(entry.get("added_at", "") or entry.get("imported_at", ""))
    fallback = added or published
    return (
        published.timestamp() if published else (fallback.timestamp() if fallback else 0),
        added.timestamp() if added else 0,
        str(entry.get("id", "") or ""),
    )


def reading_has_real_sources(data):
    sources = data.get("sources", []) if isinstance(data, dict) else []
    demo_source_urls = {normalize_reading_url(url) for url in READING_DEMO_SOURCE_URLS}
    for source in sources:
        if not isinstance(source, dict):
            continue
        source_url = normalize_reading_url(source.get("url", ""))
        if source_url and source_url not in demo_source_urls:
            return True
    return False


def is_reading_demo_entry(entry):
    if not isinstance(entry, dict):
        return False
    demo_entry_urls = {normalize_reading_url(url) for url in READING_DEMO_ENTRY_URLS}
    return normalize_reading_url(entry.get("url", "")) in demo_entry_urls


def strip_reading_demo_entries(data):
    if not isinstance(data, dict) or not reading_has_real_sources(data):
        return False
    entries = data.get("entries", []) or []
    filtered = [entry for entry in entries if not is_reading_demo_entry(entry)]
    if len(filtered) == len(entries):
        return False
    data["entries"] = filtered
    return True


def reading_entry_retention_timestamp(entry):
    entry = entry if isinstance(entry, dict) else {}
    for field in ("published_at", "added_at", "imported_at"):
        timestamp = parse_timestamp(entry.get(field, ""))
        if timestamp:
            return timestamp
    return None


def reading_entry_is_retention_protected(entry):
    entry = entry if isinstance(entry, dict) else {}
    status = normalize_reading_status(entry.get("status", ""))
    if status in {"reading", "finished"}:
        return True
    if bool(entry.get("starred", False)):
        return True
    for field in READING_RETENTION_PROTECTED_FIELDS:
        if field not in entry:
            continue
        value = entry.get(field)
        if isinstance(value, bool):
            if value:
                return True
            continue
        if value is None:
            continue
        if isinstance(value, str) and value.strip().lower() in {"", "0", "false", "no", "off", "null", "none"}:
            continue
        if value:
            return True
    for key, value in entry.items():
        key_lower = str(key or "").strip().lower()
        if "saved" not in key_lower and "important" not in key_lower:
            continue
        if key_lower in {"status", "saved", "saved_at", "important", "important_at"}:
            continue
        if value:
            return True
    return False


def reading_entry_retention_category(entry):
    entry = entry if isinstance(entry, dict) else {}
    raw_category = str(entry.get("category", "") or "").strip()
    if not raw_category:
        raw_category = str(entry.get("original_category", "") or "").strip()
    normalized = raw_category.lower()
    if normalized in READING_RETENTION_CATEGORIES:
        return normalized
    return ""


def apply_reading_retention_policy(data):
    started_at = time.monotonic()
    data = data if isinstance(data, dict) else default_reading_data()
    entries = list(data.get("entries", []) or [])
    retained_entries = list(entries)
    summary_by_category = {}
    archived_total = 0
    changed = False
    timezone = datetime.now().astimezone().tzinfo

    def retention_sort_value(entry, field):
        timestamp = parse_timestamp(entry.get(field, ""))
        if not timestamp:
            return float("-inf")
        if timestamp.tzinfo is None:
            timestamp = timestamp.replace(tzinfo=timezone)
        try:
            return timestamp.timestamp()
        except Exception:
            return float("-inf")

    for category in READING_RETENTION_CATEGORIES:
        protected_count = 0
        active_unprotected = []

        for index, entry in enumerate(retained_entries):
            if not isinstance(entry, dict):
                continue
            entry_category = reading_entry_retention_category(entry)
            if not entry_category:
                continue
            if entry_category != category:
                continue
            if normalize_reading_status(entry.get("status", "")) == "archived":
                continue
            if reading_entry_is_retention_protected(entry):
                protected_count += 1
                continue
            active_unprotected.append({
                "index": index,
                "entry": entry,
                "sort_key": (
                    retention_sort_value(entry, "published_at"),
                    retention_sort_value(entry, "added_at"),
                    retention_sort_value(entry, "imported_at"),
                    str(entry.get("id", "") or ""),
                ),
            })

        active_unprotected.sort(key=lambda item: item["sort_key"], reverse=True)
        archived_this_category = 0

        for item in active_unprotected[READING_RETENTION_CAP:]:
            entry = item["entry"]
            if normalize_reading_status(entry.get("status", "")) == "archived":
                continue
            entry["status"] = "archived"
            archived_total += 1
            archived_this_category += 1
            changed = True

        active_count = protected_count + min(len(active_unprotected), READING_RETENTION_CAP)
        summary_by_category[category] = {
            "active_count": active_count,
            "unprotected_count": len(active_unprotected),
            "protected_count": protected_count,
            "archived_count": archived_this_category,
            "kept_unprotected_count": min(len(active_unprotected), READING_RETENTION_CAP),
            "cap": READING_RETENTION_CAP,
        }

    data["entries"] = retained_entries
    data["retention_last_run_at"] = current_timestamp()
    data["retention_cap"] = READING_RETENTION_CAP
    data["retention_last_run_archived_count"] = archived_total
    data["retention_last_run_summary"] = summary_by_category
    app.logger.info(
        "reading_retention shape elapsed_ms=%.1f entries_in=%s entries_out=%s categories=%s archived_total=%s changed=%s copy_entries=1 mutates_retained_entries=1",
        (time.monotonic() - started_at) * 1000,
        len(entries),
        len(retained_entries),
        len(READING_RETENTION_CATEGORIES),
        archived_total,
        bool(changed),
    )
    return data, {
        "changed": changed,
        "archived_total": archived_total,
        "cap": READING_RETENTION_CAP,
        "category_summary": summary_by_category,
    }


def reading_hash_key(value):
    return hashlib.sha1(str(value or "").encode("utf-8")).hexdigest()[:12]


def reading_log_text(value):
    text = str(value or "")
    try:
        text.encode("ascii")
        return text
    except UnicodeEncodeError:
        return text.encode("unicode_escape").decode("ascii")


def reading_source_name_key(source):
    return str((source or {}).get("name", "") or "").strip().lower()


def reading_parse_reading_url_list(value):
    if isinstance(value, list):
        raw_values = value
    else:
        raw_text = str(value or "").strip()
        if not raw_text:
            return []
        raw_values = re.split(r"[\n,]+", raw_text)
    urls = []
    for raw_value in raw_values:
        normalized = normalize_reading_url(raw_value)
        if normalized and normalized not in urls:
            urls.append(normalized)
    return urls


def reading_source_primary_url(source):
    source = source if isinstance(source, dict) else {}
    primary_url = normalize_reading_url(source.get("primary_url", "") or "")
    url = normalize_reading_url(source.get("url", "") or "")
    return primary_url or url


def reading_source_extra_fallback_urls(source):
    source = source if isinstance(source, dict) else {}
    name_key = reading_source_name_key(source)
    url = normalize_reading_url(source.get("url", "") or "")
    primary_url = reading_source_primary_url(source)
    category = normalize_reading_category(source.get("category", "") or "")
    fallback_urls = []

    def _add(url_value):
        normalized = normalize_reading_url(url_value)
        if normalized and normalized not in fallback_urls and normalized != primary_url:
            fallback_urls.append(normalized)

    if "morocco world news" in name_key and "moroccoworldnews.com" in url:
        _add("https://www.moroccoworldnews.com/rss")
        _add("https://www.moroccoworldnews.com/feed/")
        _add("https://www.moroccoworldnews.com/feed")
        _add("https://moroccoworldnews.com/feed")
        _add("https://www.moroccoworldnews.com/opinion/feed/")
        _add("https://moroccoworldnews.com/rss")
    if "howiyapress" in name_key or "howiyapress.com" in url:
        if "/category/" in url or category in {"news", "culture", "opinion"}:
            _add("https://howiyapress.com/feed/")
            _add("https://howiyapress.com/feed")
            _add("https://www.howiyapress.com/feed/")
            _add("https://www.howiyapress.com/feed")
            _add("https://howiyapress.com/rss")
            _add("https://www.howiyapress.com/rss")
    if "assabah.ma" in url or "assabah" in name_key:
        if "/category/" in url:
            _add("https://assabah.ma/feed")
            _add("https://assabah.ma/feed/")
            _add("https://www.assabah.ma/feed")
            _add("https://www.assabah.ma/feed/")
            _add("https://assabah.ma/rss")
            _add("https://www.assabah.ma/rss")
    if "al jazeera english" in name_key and "opinion" in name_key:
        _add("https://www.aljazeera.com/xml/rss/all.xml")
        _add("https://www.aljazeera.com/rss")

    return fallback_urls


def reading_source_feed_candidate_urls(source):
    source = source if isinstance(source, dict) else {}
    candidate_urls = []
    primary_url = reading_source_primary_url(source)
    url = normalize_reading_url(source.get("url", "") or "")
    raw_fallback_urls = source.get("fallback_urls", source.get("feed_fallback_urls", []))
    if isinstance(raw_fallback_urls, str):
        raw_fallback_urls = [raw_fallback_urls]
    for candidate_url in [primary_url, url] + list(raw_fallback_urls or []) + reading_source_extra_fallback_urls(source):
        normalized_candidate = normalize_reading_url(candidate_url)
        if normalized_candidate and normalized_candidate not in candidate_urls:
            candidate_urls.append(normalized_candidate)
    return candidate_urls


def normalize_reading_source(source, index=0):
    item = source if isinstance(source, dict) else {}
    url = str(item.get("url", "") or "").strip()
    primary_url = str(item.get("primary_url", "") or "").strip() or url
    name = str(item.get("name", "") or "").strip() or f"Source {index + 1}"
    if normalize_reading_url(url) == READING_MAP_NEWS_ENGLISH_FEED_URL:
        name = READING_MAP_NEWS_ENGLISH_NAME
    category = normalize_reading_category(item.get("category", "") or "")
    topic = normalize_reading_topic(item.get("topic", "") or "", category)
    topic_display = reading_visible_topic_label(topic, category)
    source_id = str(item.get("id", "") or item.get("source_id", "") or "").strip()
    fallback_urls = []
    raw_fallback_urls = item.get("fallback_urls", item.get("feed_fallback_urls", []))
    if isinstance(raw_fallback_urls, str):
        raw_fallback_urls = [raw_fallback_urls]
    for fallback_url in raw_fallback_urls or []:
        normalized_fallback = normalize_reading_url(fallback_url)
        if normalized_fallback and normalized_fallback not in fallback_urls and normalized_fallback != normalize_reading_url(url):
            fallback_urls.append(normalized_fallback)
    if not source_id:
        source_id = f"reading-src-{reading_hash_key('|'.join([name.lower(), normalize_reading_url(url).lower(), topic.lower()]))}"
    added_at = str(item.get("added_at", "") or "").strip() or current_timestamp()
    updated_at = str(item.get("updated_at", "") or "").strip() or added_at
    note = str(item.get("note", "") or "").strip()
    status = str(item.get("status", "") or "").strip()
    last_sync_status = str(item.get("last_sync_status", "") or "").strip()
    last_sync_error = str(item.get("last_sync_error", "") or "").strip()
    last_sync_message = str(item.get("last_sync_message", "") or "").strip()
    last_sync_already_had_count = int(item.get("last_sync_already_had_count", 0) or item.get("last_sync_existing_count", 0) or 0)
    if not last_sync_already_had_count and last_sync_message:
        already_had_match = re.search(r"already had\s+(\d+)", last_sync_message, flags=re.IGNORECASE)
        if already_had_match:
            last_sync_already_had_count = int(already_had_match.group(1) or 0)
    last_sync_missing_key_count = int(item.get("last_sync_missing_key_count", 0) or 0)
    if not last_sync_missing_key_count and last_sync_message:
        missing_key_match = re.search(r"Skipped\s+(\d+)\s+item\(s\)\s+with no stable URL or id", last_sync_message, flags=re.IGNORECASE)
        if missing_key_match:
            last_sync_missing_key_count = int(missing_key_match.group(1) or 0)
    zero_import_streak = int(item.get("last_sync_zero_import_streak", 0) or 0)
    if last_sync_status.lower().startswith("error:"):
        if not last_sync_error:
            last_sync_error = last_sync_status.split(":", 1)[1].strip()
        last_sync_status = "error"
    last_sync_attempts = []
    raw_last_sync_attempts = item.get("last_sync_attempts", [])
    if isinstance(raw_last_sync_attempts, list):
        for attempt in raw_last_sync_attempts:
            if not isinstance(attempt, dict):
                continue
            normalized_attempt = {
                "attempt": int(attempt.get("attempt", 0) or 0),
                "feed_url": normalize_reading_url(attempt.get("feed_url", "") or attempt.get("request_url", "") or ""),
                "final_url": normalize_reading_url(attempt.get("final_url", "") or ""),
                "status_code": int(attempt.get("status_code", 0) or 0),
                "content_type": str(attempt.get("content_type", "") or "").strip(),
                "elapsed_ms": int(attempt.get("elapsed_ms", 0) or 0),
                "error": str(attempt.get("error", "") or "").strip(),
            }
            if any(normalized_attempt.values()):
                last_sync_attempts.append(normalized_attempt)
    return {
        "id": source_id,
        "name": name,
        "url": url,
        "primary_url": primary_url,
        "fallback_urls": fallback_urls,
        "topic": topic,
        "topic_display": topic_display,
        "category": category,
        "note": note,
        "status": status,
        "active": normalize_reading_bool(item.get("active", True), default=True),
        "added_at": added_at,
        "updated_at": updated_at,
        "last_synced_at": str(item.get("last_synced_at", "") or "").strip(),
        "last_sync_count": int(item.get("last_sync_count", 0) or 0),
        "last_sync_raw_count": int(item.get("last_sync_raw_count", 0) or 0),
        "last_sync_normalized_count": int(item.get("last_sync_normalized_count", 0) or 0),
        "last_sync_imported_count": int(item.get("last_sync_imported_count", 0) or 0),
        "last_sync_already_had_count": last_sync_already_had_count,
        "last_sync_missing_key_count": last_sync_missing_key_count,
        "last_sync_zero_import_streak": zero_import_streak,
        "last_sync_status_code": int(item.get("last_sync_status_code", 0) or 0),
        "last_sync_content_type": str(item.get("last_sync_content_type", "") or "").strip(),
        "last_sync_feed_kind": str(item.get("last_sync_feed_kind", "") or "").strip(),
        "last_sync_resolved_url": str(item.get("last_sync_resolved_url", "") or "").strip(),
        "last_sync_successful_url": str(item.get("last_sync_successful_url", "") or "").strip(),
        "last_sync_tried_urls": list(item.get("last_sync_tried_urls", []) or []) if isinstance(item.get("last_sync_tried_urls", []), list) else [],
        "last_sync_retry_count": int(item.get("last_sync_retry_count", 0) or 0),
        "last_sync_timeout_reason": str(item.get("last_sync_timeout_reason", "") or "").strip(),
        "last_sync_feedparser_bozo": str(item.get("last_sync_feedparser_bozo", "") or "").strip(),
        "last_sync_feedparser_bozo_exception": str(item.get("last_sync_feedparser_bozo_exception", "") or "").strip(),
        "last_sync_feedparser_entry_count": int(item.get("last_sync_feedparser_entry_count", 0) or 0),
        "last_sync_source_fallback_used": normalize_reading_bool(item.get("last_sync_source_fallback_used", False), default=False),
        "last_sync_attempts": last_sync_attempts,
        "last_sync_reason": str(item.get("last_sync_reason", "") or "").strip(),
        "last_sync_message": last_sync_message,
        "last_sync_status": last_sync_status,
        "last_sync_error": last_sync_error,
        "successful_url": str(item.get("successful_url", "") or "").strip(),
        "last_successful_url": str(item.get("last_successful_url", "") or "").strip(),
        "last_sync_final_url": str(item.get("last_sync_final_url", item.get("last_sync_resolved_url", "")) or "").strip(),
    }


def reading_source_is_blocked(source):
    source = source if isinstance(source, dict) else {}
    status = str(source.get("last_sync_status", "") or "").strip().lower()
    status_code = int(source.get("last_sync_status_code", 0) or 0)
    error = str(source.get("last_sync_error", "") or "").strip().lower()
    message = str(source.get("last_sync_message", "") or "").strip().lower()
    if status == "blocked_source":
        return True
    if status_code == 403:
        return True
    return "http 403" in error or "http 403" in message


def reading_source_sync_looks_proxy_blocked(result):
    result = result if isinstance(result, dict) else {}
    status = str(result.get("status", "") or "").strip().lower()
    status_code = int(result.get("status_code", 0) or 0)
    error = str(result.get("error", "") or "").strip().lower()
    reason = str(result.get("reason", "") or "").strip().lower()
    timeout_reason = str(result.get("timeout_reason", "") or "").strip().lower()
    feed_kind = str(result.get("feed_kind", "") or "").strip().lower()
    blob = " ".join((status, error, reason, timeout_reason, feed_kind))
    if status not in {"error", "blocked_source"}:
        return False
    if status_code == 403:
        return True
    return any(token in blob for token in ("proxyerror", "proxy error", "http 403", "403 forbidden", "forbidden"))


def reading_sync_should_preserve_snapshot(source_results, active_source_count, imported_total=0):
    source_results = list(source_results or [])
    active_source_count = int(active_source_count or 0)
    if not active_source_count or imported_total > 0:
        return False
    if len(source_results) != active_source_count:
        return False
    return all(reading_source_sync_looks_proxy_blocked(result) for result in source_results)


def reading_source_sync_reason(source):
    source = source if isinstance(source, dict) else {}
    status = str(source.get("last_sync_status", "") or "").strip().lower()
    error = str(source.get("last_sync_error", "") or "").strip()
    feed_kind = str(source.get("last_sync_feed_kind", "") or "").strip().lower()
    content_type = str(source.get("last_sync_content_type", "") or "").strip().lower()
    status_code = int(source.get("last_sync_status_code", 0) or 0)
    raw_count = int(source.get("last_sync_raw_count", 0) or source.get("last_sync_count", 0) or 0)
    normalized_count = int(source.get("last_sync_normalized_count", 0) or 0)
    imported_count = int(source.get("last_sync_imported_count", 0) or 0)
    already_had_count = int(source.get("last_sync_already_had_count", 0) or 0)
    missing_key_count = int(source.get("last_sync_missing_key_count", 0) or 0)
    zero_import_streak = int(source.get("last_sync_zero_import_streak", 0) or 0)
    if reading_source_is_blocked(source):
        return "This source is blocking automated fetches from the sync environment."
    if not source.get("active", True):
        return "Source paused"
    if not str(source.get("url", "") or "").strip():
        return "Missing feed URL"
    if status == "error":
        return f"Fetch failed: {error}" if error else "Fetch failed"
    if not source.get("last_synced_at"):
        return "Not synced yet"
    if raw_count == 0:
        if imported_count == 0:
            return "No new items"
        if "html" in content_type or feed_kind == "unknown":
            return "No RSS/Atom items found"
        return "Feed empty"
    if normalized_count == 0:
        return "Parser/normalization issue"
    if imported_count == 0 and zero_import_streak >= 3:
        return "Repeated zero imports"
    if imported_count == 0 and already_had_count >= normalized_count:
        return "No new items"
    if missing_key_count:
        return f"Skipped {missing_key_count} item(s) with no stable URL or id"
    return "New items imported" if imported_count else "No new items"


def reading_source_health(source, known_entries=0):
    source = source if isinstance(source, dict) else {}
    status = str(source.get("last_sync_status", "") or "").strip().lower()
    feed_kind = str(source.get("last_sync_feed_kind", "") or "").strip().lower()
    content_type = str(source.get("last_sync_content_type", "") or "").strip().lower()
    raw_count = int(source.get("last_sync_raw_count", 0) or source.get("last_sync_count", 0) or 0)
    normalized_count = int(source.get("last_sync_normalized_count", 0) or 0)
    imported_count = int(source.get("last_sync_imported_count", 0) or 0)
    missing_key_count = int(source.get("last_sync_missing_key_count", 0) or 0)
    zero_import_streak = int(source.get("last_sync_zero_import_streak", 0) or 0)
    last_synced_at = parse_timestamp(source.get("last_synced_at", ""))
    if last_synced_at:
        now = datetime.now().astimezone()
        if last_synced_at.tzinfo is None:
            last_synced_at = last_synced_at.replace(tzinfo=now.tzinfo)
        age_days = max((now - last_synced_at.astimezone()).total_seconds() / 86400.0, 0.0)
    else:
        age_days = None
    if not source.get("active", True):
        return "paused"
    if not str(source.get("url", "") or "").strip() or not source.get("last_synced_at"):
        return "warning"
    if reading_source_is_blocked(source):
        return "failing"
    if status == "error":
        return "failing"
    if age_days is not None and age_days >= 14 and imported_count == 0:
        return "warning"
    if zero_import_streak >= 3 and raw_count > 0 and imported_count == 0:
        return "warning"
    if raw_count == 0 and imported_count == 0 and not known_entries:
        return "healthy"
    if normalized_count == 0 or feed_kind == "unknown" or "html" in content_type:
        return "warning"
    if missing_key_count:
        return "warning"
    return "healthy"


def reading_source_health_label(source, known_entries=0):
    status = reading_source_admin_status(source, known_entries=known_entries)
    return status.get("label", "Needs review")


def reading_source_sync_age_label(source):
    last_synced_at = parse_timestamp((source or {}).get("last_synced_at", ""))
    if not last_synced_at:
        return "Never"
    now = datetime.now().astimezone()
    if last_synced_at.tzinfo is None:
        last_synced_at = last_synced_at.replace(tzinfo=now.tzinfo)
    delta = now - last_synced_at.astimezone()
    total_hours = max(int(delta.total_seconds() // 3600), 0)
    if total_hours < 24:
        return f"{max(total_hours, 1)}h ago"
    total_days = max(int(delta.total_seconds() // 86400), 0)
    if total_days < 7:
        return f"{max(total_days, 1)}d ago"
    total_weeks = max(int(total_days // 7), 1)
    return f"{total_weeks}w ago"


def reading_source_sync_age_days(source):
    last_synced_at = parse_timestamp((source or {}).get("last_synced_at", ""))
    if not last_synced_at:
        return None
    now = datetime.now().astimezone()
    if last_synced_at.tzinfo is None:
        last_synced_at = last_synced_at.replace(tzinfo=now.tzinfo)
    return max((now - last_synced_at.astimezone()).total_seconds() / 86400.0, 0.0)


def reading_source_admin_status(source, known_entries=0):
    source = source if isinstance(source, dict) else {}
    health_state = reading_source_health(source, known_entries=known_entries)
    status = str(source.get("last_sync_status", "") or "").strip().lower()
    error = str(source.get("last_sync_error", "") or "").strip()
    feed_kind = str(source.get("last_sync_feed_kind", "") or "").strip().lower()
    content_type = str(source.get("last_sync_content_type", "") or "").strip().lower()
    raw_count = int(source.get("last_sync_raw_count", 0) or source.get("last_sync_count", 0) or 0)
    normalized_count = int(source.get("last_sync_normalized_count", 0) or 0)
    imported_count = int(source.get("last_sync_imported_count", 0) or 0)
    already_had_count = int(source.get("last_sync_already_had_count", 0) or 0)
    missing_key_count = int(source.get("last_sync_missing_key_count", 0) or 0)
    zero_import_streak = int(source.get("last_sync_zero_import_streak", 0) or 0)
    age_days = reading_source_sync_age_days(source)
    reason = reading_source_sync_reason(source)
    last_sync_age_label = reading_source_sync_age_label(source)
    last_sync_attempts = list(source.get("last_sync_attempts", []) or [])
    last_sync_final_url = str(source.get("last_sync_final_url", "") or "").strip() or str(source.get("last_sync_resolved_url", "") or "").strip()
    last_successful_url = str(source.get("last_successful_url", "") or "").strip() or str(source.get("successful_url", "") or "").strip()

    if not source.get("active", True):
        return {
            "state": "paused",
            "visual_state": "paused",
            "label": "Inactive",
            "note": "Source is paused.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if not str(source.get("url", "") or "").strip():
        return {
            "state": "needs_review",
            "visual_state": "warning",
            "label": "Needs review",
            "note": "Missing feed URL.",
            "detail": "Add a feed URL before the next sync.",
            "age_label": last_sync_age_label,
        }
    if reading_source_is_blocked(source):
        return {
            "state": "blocked_source",
            "visual_state": "failing",
            "label": "Blocked by source",
            "note": "This source is blocking automated fetches from the sync environment.",
            "detail": reason,
            "age_label": last_sync_age_label,
            "final_url": last_sync_final_url,
            "last_successful_url": last_successful_url,
            "attempts": last_sync_attempts,
        }
    if status == "error" or feed_kind == "error" or error:
        return {
            "state": "fetch_error",
            "visual_state": "failing",
            "label": "Fetch error",
            "note": reason if reason.startswith("Fetch blocked by source") else (error or "The feed fetch failed."),
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if not str(source.get("last_synced_at", "") or "").strip():
        return {
            "state": "not_synced",
            "visual_state": "warning",
            "label": "Needs review",
            "note": "Not synced yet.",
            "detail": "Run a sync to collect diagnostics.",
            "age_label": last_sync_age_label,
        }
    if zero_import_streak >= 3 and raw_count > 0 and imported_count == 0:
        return {
            "state": "repeated_zero_imports",
            "visual_state": "warning",
            "label": "Repeated zero imports",
            "note": f"{zero_import_streak} zero-import runs in a row.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if age_days is not None and age_days >= 14 and imported_count == 0:
        return {
            "state": "stale",
            "visual_state": "warning",
            "label": "Stale",
            "note": f"No imports for {last_sync_age_label}.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if health_state == "warning":
        return {
            "state": "needs_review",
            "visual_state": "warning",
            "label": "Needs review",
            "note": "The feed needs a quick look.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if normalized_count == 0 and raw_count > 0:
        return {
            "state": "needs_review",
            "visual_state": "warning",
            "label": "Needs review",
            "note": "The feed parsed poorly.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if missing_key_count:
        return {
            "state": "needs_review",
            "visual_state": "warning",
            "label": "Needs review",
            "note": f"{missing_key_count} item(s) lacked a stable key.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if imported_count > 0:
        return {
            "state": "healthy",
            "visual_state": "healthy",
            "label": "Healthy",
            "note": f"Imported {imported_count} new item(s).",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    if imported_count == 0 and (already_had_count >= normalized_count or raw_count == 0):
        return {
            "state": "ok_no_new",
            "visual_state": "healthy",
            "label": "No new items",
            "note": "Feed fetched successfully and had no new items.",
            "detail": reason,
            "age_label": last_sync_age_label,
        }
    return {
        "state": "ok_no_new" if imported_count == 0 else "healthy",
        "visual_state": "healthy",
        "label": "No new items" if imported_count == 0 else "Healthy",
        "note": "Feed fetched successfully with no new entries." if imported_count == 0 else "Source synced cleanly.",
        "detail": reason,
        "age_label": last_sync_age_label,
    }


def reading_is_rss_source(source):
    source = source if isinstance(source, dict) else {}
    url = str(source.get("url", "") or "").strip()
    name = str(source.get("name", "") or "").strip().lower()
    if not url:
        return False
    if "readwise" in name:
        return False
    return True


def normalize_reading_entry(entry, index=0, source_lookup=None, source_category_lookup=None, include_content=True, include_body_image_scan=True):
    item = entry if isinstance(entry, dict) else {}
    published_at = str(item.get("published_at", "") or "").strip()
    added_at = str(item.get("added_at", "") or "").strip()
    source_name = str(item.get("source", "") or "Unknown Source").strip()
    source_id = str(item.get("source_id", "") or "").strip()
    source_lookup = source_lookup if isinstance(source_lookup, dict) else {}
    source_category_lookup = source_category_lookup if isinstance(source_category_lookup, dict) else {}
    if not source_id:
        source_id = source_lookup.get(source_name.lower(), "")
    source_name_lookup = source_lookup.get("__source_name_lookup__", {}) if isinstance(source_lookup.get("__source_name_lookup__", {}), dict) else {}
    if source_id and isinstance(source_name_lookup, dict):
        canonical_source_name = str(source_name_lookup.get(source_id, "") or "").strip()
        if canonical_source_name:
            if not source_name or source_lookup.get(source_name.lower(), "") == source_id:
                source_name = canonical_source_name
    url = normalize_reading_url(item.get("url", ""))
    title = str(item.get("title", "") or "").strip() or "Untitled article"
    original_url = normalize_reading_url(item.get("original_url", "")) or url
    entry_seed = url or "|".join([source_name.lower(), title.lower(), published_at.lower()])
    entry_id = str(item.get("id", "") or item.get("entry_id", "") or "").strip()
    if not entry_id:
        entry_id = f"reading-{reading_hash_key(entry_seed or str(index))}"
    topic = str(item.get("topic", "") or "").strip()
    excerpt = normalize_reading_space(item.get("excerpt", "") or item.get("summary", "")) if include_content else ""
    content_text = str(item.get("content_text", "") or "").strip() if include_content else ""
    content_html = str(item.get("content_html", "") or "").strip() if include_content else ""
    if include_content and not excerpt and content_text:
        excerpt = normalize_reading_space(content_text)[:420].strip()
    content_score = int(item.get("content_score", 0) or 0)
    if include_content and not content_score:
        content_score = reading_entry_content_score({
            "content_html": content_html,
            "content_text": content_text,
            "excerpt": excerpt,
            "image_url": item.get("image_url", ""),
            "lead_image_url": item.get("lead_image_url", ""),
            "author_image_url": item.get("author_image_url", ""),
            "author": item.get("author", ""),
        })
    image_url = absolutize_reading_url(item.get("image_url", ""), original_url or url)
    lead_image_url = absolutize_reading_url(item.get("lead_image_url", ""), original_url or url)
    image_source = str(item.get("image_source", "") or "").strip().lower()
    lead_image_kind = str(item.get("lead_image_kind", "") or "").strip().lower()
    author_name = str(item.get("author", "") or "").strip()
    author_image_url = absolutize_reading_url(item.get("author_image_url", ""), original_url or url)
    feed_source_url = str(item.get("feed_url", "") or "").strip()
    image_candidates = []
    if lead_image_url:
        image_candidates.append({
            "url": lead_image_url,
            "kind": "explicit" if lead_image_kind == "explicit" else "feed_cover",
            "attrs": {},
        })
    if image_url:
        image_candidates.append({
            "url": image_url,
            "kind": "feed_cover" if image_source == "feed_cover" else "body",
            "attrs": {},
        })
    body_image_url = ""
    if include_body_image_scan and content_html and not (lead_image_url or image_url):
        body_image_url = extract_reading_image_from_html(content_html, original_url or url, source_url=feed_source_url, source_name=source_name)
    if body_image_url:
        image_candidates.append({"url": body_image_url, "kind": "body", "attrs": {}})
    best_image = reading_pick_best_image_candidate(image_candidates, article_url=original_url or url, source_url=feed_source_url, source_name=source_name)
    if best_image.get("url"):
        image_url = best_image.get("url", "")
        if best_image.get("kind") in {"explicit", "feed_cover"}:
            lead_image_url = best_image.get("url", "")
            lead_image_kind = best_image.get("kind", "")
        else:
            lead_image_url = ""
            lead_image_kind = ""
    else:
        if reading_is_bad_image_candidate(image_url, article_url=original_url or url, source_url=feed_source_url, source_name=source_name):
            image_url = ""
        if reading_is_bad_image_candidate(lead_image_url, article_url=original_url or url, source_url=feed_source_url, source_name=source_name):
            lead_image_url = ""
            lead_image_kind = ""
    if author_image_url and not reading_is_valid_author_avatar(
        author_image_url,
        article_url=original_url or url,
        author_name=author_name,
        hero_image=lead_image_url,
        entry_image=image_url,
    ):
        author_image_url = ""
    source_category = source_category_lookup.get(source_id, "") or source_category_lookup.get(source_name.lower(), "")
    raw_category = str(source_category or item.get("category", "") or "").strip()
    category = normalize_reading_category(raw_category)
    topic_display = reading_visible_topic_label(topic, category)
    normalized_status = normalize_reading_status(item.get("status", ""))
    saved_state = normalize_reading_bool(item.get("saved", None), default=False) or bool(item.get("starred", False))
    for saved_key in ("important", "bookmarked", "bookmark", "pinned"):
        saved_state = saved_state or normalize_reading_bool(item.get(saved_key, False), default=False)
    extraction_status = str(item.get("extraction_status", "") or "").strip()
    if extraction_status and extraction_status not in READING_CONTENT_CACHE_STATUSES:
        extraction_status = ""
    normalized = {
        "id": entry_id,
        "source_id": source_id,
        "source": source_name,
        "source_dir": reading_short_text_direction(source_name),
        "title": title,
        "title_dir": reading_title_direction(title),
        "url": url,
        "original_url": original_url,
        "external_id": str(item.get("external_id", "") or item.get("guid", "") or item.get("entry_guid", "") or item.get("feed_entry_id", "") or "").strip(),
        "published_at": published_at,
        "published_display": str(item.get("published_display", "") or "").strip() or format_timestamp_label(published_at, default=""),
        "added_at": added_at,
        "added_display": str(item.get("added_display", "") or "").strip() or format_timestamp_label(added_at, default=""),
        "imported_at": str(item.get("imported_at", "") or added_at).strip(),
        "status": normalized_status,
        "read": normalized_status != "unread",
        "saved": saved_state,
        "starred": bool(item.get("starred", False)),
        "topic": topic,
        "topic_display": topic_display,
        "category": category,
        "image_url": image_url,
        "lead_image_url": lead_image_url,
        "image_source": image_source,
        "lead_image_kind": lead_image_kind if lead_image_kind in {"explicit", "feed_cover"} else "",
        "author": author_name,
        "author_image_url": author_image_url,
        "summary": excerpt,
        "excerpt": excerpt,
        "content_html": content_html,
        "content_text": content_text,
        "content_score": content_score,
        "extraction_status": extraction_status,
        "extraction_error": str(item.get("extraction_error", "") or "").strip(),
        "content_cached_at": str(item.get("content_cached_at", "") or "").strip(),
        "origin": str(item.get("origin", "") or "manual").strip() or "manual",
        "imported_from": str(item.get("imported_from", "") or "").strip(),
        "feed_url": str(item.get("feed_url", "") or "").strip(),
        "canonical_url": url,
    }
    if raw_category and raw_category.lower() != category:
        normalized["original_category"] = raw_category
    for key, value in item.items():
        key_name = str(key or "").strip()
        key_lower = key_name.lower()
        if not key_name or key_name in normalized:
            continue
        if key_lower in READING_RETENTION_PROTECTED_FIELDS or "saved" in key_lower or "important" in key_lower:
            normalized[key_name] = value
    return normalized


