@app.route("/login", methods=["GET", "POST"])
def login():
    if not dragon_auth_enabled():
        return redirect(url_for("home"))
    if dragon_is_authenticated():
        return redirect(dragon_next_url())
    error_message = ""
    next_url = dragon_next_url()
    if request.method == "POST":
        username = str(request.form.get("username", "") or "").strip()
        password = str(request.form.get("password", "") or "")
        if username == DRAGON_ADMIN_USERNAME and password == DRAGON_ADMIN_PASSWORD:
            session["dragon_authenticated"] = True
            session.permanent = True
            return redirect(next_url)
        error_message = "Wrong username or password."
    return render_template("login.html", next_url=next_url, error_message=error_message)


@app.route("/logout")
def logout():
    session.pop("dragon_authenticated", None)
    next_url = dragon_next_url(default_endpoint="login")
    return redirect(next_url)


@app.route("/refresh")
def refresh():
    scope = (request.args.get("scope") or "all").strip().lower()
    next_url = request.args.get("next") or url_for("home")
    if not DRAGON_ALLOW_WEB_REFRESH_SYNC:
        flash("Full sync is disabled online to avoid timeouts. Use Admin sync or scheduled sync.", "info")
        return redirect(next_url)

    refresh_films = scope in {"all", "films", "movies", "movie"}
    refresh_youtube = scope in {"all", "youtube", "playlists"}
    pockettube_section_name = ""
    if refresh_youtube:
        try:
            parsed_next = urllib.parse.urlparse(next_url)
            next_path = str(parsed_next.path or "").strip()
        except Exception:
            next_path = str(next_url or "").strip()
        section_match = re.fullmatch(r"/section/([^/?#]+)", next_path)
        if section_match:
            section_slug_value = str(section_match.group(1) or "").strip()
            pockettube_section = _pockettube_section_membership_context(section_slug_value, admin_data=load_admin_data())
            if pockettube_section.get("channel_count", 0):
                pockettube_section_name = pockettube_section.get("section_name", section_slug_value) or section_slug_value
    if refresh_films:
        clear_film_cache_entry()
    if refresh_films and (TMDB_API_KEY or "").strip() and (NOTION_TOKEN or "").strip() and (NOTION_DATABASE_ID or "").strip():
        try:
            run_tmdb_sync_enrichment()
        except Exception:
            pass
    reset_playlists_metadata()
    refresh_all_cached_data(
        refresh_films=refresh_films,
        refresh_youtube=refresh_youtube,
        pockettube_section_name=pockettube_section_name,
    )
    return redirect(next_url)


@app.route("/api/section-refresh", methods=["POST"])
def section_refresh():
    payload = request.get_json(silent=True) if request.is_json else {}
    payload = payload if isinstance(payload, dict) else {}
    section = str(payload.get("section", "") or "").strip().lower()
    scope = str(payload.get("scope", "") or "").strip()
    _return_url = str(payload.get("return_url", "") or "").strip()
    handler = SECTION_REFRESH_HANDLERS.get(section)
    if handler is None:
        return jsonify({
            "ok": False,
            "section": section,
            "message": "Unknown section.",
            "refreshed_at": current_timestamp(),
            "reload": False,
        }), 400
    try:
        result = handler(scope=scope)
    except Exception as exc:
        app.logger.warning("section_refresh failed section=%s error=%s", section, exc)
        return jsonify({
            "ok": False,
            "section": section,
            "message": str(exc) or "Section refresh failed.",
            "refreshed_at": current_timestamp(),
            "reload": False,
        }), 500
    result = dict(result or {})
    return jsonify({
        "ok": True,
        "section": str(result.get("section", section) or section),
        "message": str(result.get("message", "Section refreshed.") or "Section refreshed."),
        "refreshed_at": current_timestamp(),
        "reload": True,
    })


@app.route("/api/section-sync", methods=["POST"])
def section_sync():
    payload = request.get_json(silent=True) if request.is_json else {}
    payload = payload if isinstance(payload, dict) else {}
    section = str(payload.get("section", "") or "").strip().lower()
    scope = str(payload.get("scope", "") or "").strip()
    handler = SECTION_SYNC_HANDLERS.get(section)
    if handler is None:
        return jsonify({
            "ok": False,
            "section": section,
            "status": "failed",
            "message": "Unknown section.",
            "synced_at": current_timestamp(),
            "refresh": None,
            "reload": False,
        }), 400

    try:
        sync_result = dict(handler(scope=scope) or {})
        sync_status = str(sync_result.get("status", "synced") or "synced")
        refresh_result = None
        if sync_status in {"synced", "pending", "unsupported"}:
            refresh_result = _run_section_refresh(section, scope=scope)
    except Exception as exc:
        app.logger.warning("section_sync failed section=%s error=%s", section, exc)
        return jsonify({
            "ok": False,
            "section": section,
            "status": "failed",
            "message": str(exc) or "Section sync failed.",
            "synced_at": current_timestamp(),
            "refresh": None,
            "reload": False,
        }), 500

    return jsonify({
        "ok": True,
        "section": section,
        "status": sync_status,
        "message": str(sync_result.get("message", "Section synced.") or "Section synced."),
        "synced_at": current_timestamp(),
        "refresh": refresh_result,
        "reload": True,
    })


